using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEngine.UI;using UnityEditor;
public static class ValidateShopChest086 {
 static void Capture(Transform h,Vector3 pos,Vector3 aim,string file){var g=new GameObject("Temporary_Shop086_Camera");var rt=new RenderTexture(1600,1100,24);var tx=new Texture2D(1600,1100,TextureFormat.RGB24,false);var old=RenderTexture.active;try{var c=g.AddComponent<Camera>();c.transform.position=h.TransformPoint(pos);c.transform.LookAt(h.TransformPoint(aim));c.fieldOfView=102;c.farClipPlane=120;c.targetTexture=rt;c.Render();RenderTexture.active=rt;tx.ReadPixels(new Rect(0,0,1600,1100),0,0);tx.Apply();File.WriteAllBytes("Docs/assets/examples/"+file+".png",tx.EncodeToPNG());}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(g);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tx);}}
 static string Reach(Transform h,Vector3 target){var g=new GameObject("Temporary_Shop086_Player");try{var cc=g.AddComponent<CharacterController>();cc.height=1.8f;cc.radius=.35f;cc.center=new Vector3(0,.9f,0);cc.stepOffset=.3f;g.transform.position=h.TransformPoint(new Vector3(0,.55f,-4.5f));Physics.SyncTransforms();for(int j=0;j<170;j++){var p=h.InverseTransformPoint(g.transform.position);if(p.z>=target.z-.02f)break;cc.Move(h.TransformVector(new Vector3(0,0,.04f))+Vector3.down*.025f);}for(int j=0;j<110;j++){var p=h.InverseTransformPoint(g.transform.position);float d=target.x-p.x;if(Mathf.Abs(d)<.02f)break;cc.Move(h.TransformVector(new Vector3(Mathf.Clamp(d,-.04f,.04f),0,0))+Vector3.down*.025f);}var end=h.InverseTransformPoint(g.transform.position);if(Vector2.Distance(new Vector2(end.x,end.z),new Vector2(target.x,target.z))>.16f||!cc.isGrounded)throw new Exception("Approach blocked "+end+" target "+target);return end.ToString("F3");}finally{UnityEngine.Object.DestroyImmediate(g);}}
 public static string Main(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/CastleServicesWorkshop.unity"||scene.isDirty)throw new Exception("Saved castle required");var hs=GameObject.Find("Castle_Services_Prototype").transform.Find("03_Service_Houses");var shop=hs.Find("01_Supplies");var tr=hs.Find("03_LootTrader");var report=new StringBuilder();
 var points=shop.Find("15_Gameplay_Source/StorePoints").Cast<Transform>().Where(t=>t.name.StartsWith("storePoint")).ToArray();if(points.Length!=3||shop.Find("25_Supplies_Counters").childCount!=3)throw new Exception("Slots/counters mismatch");
 foreach(Transform rug in shop.Find("27_Supplies_Pickup_Mats"))report.AppendLine("Shop Player-size approach PASS "+Reach(shop,rug.localPosition));
 foreach(var point in points){var buy=point.GetComponentsInChildren<Transform>(true).First(t=>t.name=="buyPoint");foreach(string item in new[]{"coal","Lantern","Fence"}){var a=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Prefabs/Items/"+item+".prefab");var col=a.GetComponent<BoxCollider>();if(col==null)throw new Exception("Expected source collider "+item);var b=new Bounds(buy.position+buy.rotation*Vector3.Scale(col.center,a.transform.localScale),Vector3.Scale(col.size,a.transform.localScale));var half=b.size*.5f;var near=Physics.OverlapBox(b.center,half,buy.rotation,~0,QueryTriggerInteraction.Ignore);if(near.Any(c=>c.transform.IsChildOf(shop)&&c.enabled&&!c.isTrigger))throw new Exception("Drop intersects solid geometry "+point.name+" "+item+" "+b);report.AppendLine(point.name+" "+item+" source collider clear at spawn, size="+b.size);}}
 var sell=tr.Find("15_Gameplay_Source/SellPoint");var trigger=sell.GetComponent<BoxCollider>();var money=sell.GetComponentsInChildren<Transform>(true).First(t=>t.name=="MoneyBagPoint");var mats=tr.Find("23_Trader_Service_Mats");foreach(Transform rug in mats)report.AppendLine("Trader Player-size approach PASS "+Reach(tr,rug.localPosition));if(tr.Find("16_Run_Interior/Treasury_Chest")!=null||tr.Find("16_Run_Interior/Finds_Delivery_Chest")==null)throw new Exception("Chest relocation missing");if(Vector3.Distance(tr.InverseTransformPoint(money.position),mats.Find("Trade_Reward_Rug").localPosition+Vector3.up*.01f)>.001f)throw new Exception("Reward displaced");if(!Physics.OverlapBox(tr.TransformPoint(mats.Find("Finds_Delivery_Rug").localPosition+Vector3.up*.35f),new Vector3(.1f,.2f,.1f),tr.rotation,~0,QueryTriggerInteraction.Collide).Contains(trigger))throw new Exception("Finds trigger misaligned");
 if(shop.GetComponentsInChildren<TextMesh>(true).Length!=0||tr.GetComponentsInChildren<TextMesh>(true).Length!=0)throw new Exception("Non UI label added");
 report.AppendLine("No new gameplay components or fixed product names; existing UI/StorePoint names remain runtime-driven. No promotional text added. Editor stock previews hidden to avoid fictitious stock.");
 Capture(shop,new Vector3(0,2.25f,-2.60f),new Vector3(0,1.15f,1.50f),"Supplies_Counters086_Interior");Capture(tr,new Vector3(0,2.35f,-2.65f),new Vector3(0,1.25f,1.25f),"Trader_Chest086_Interior");
 report.AppendLine("Edit Mode geometry checks only; actual purchase, sale, reward and item fall need gameplay acceptance after restoring Fusion.");File.WriteAllText("Docs/assets/examples/SHOP_CHEST086_VALIDATION.txt",report.ToString());return report.ToString();}
}
